static boolean placeTile(boolean[][] g, int r, int c, int x, int y) {
    // Check if the tile placement would exceed the grid boundaries for both orientations
    if ((r + x > g.length || c + y > g[0].length) && (r + y > g.length || c + x > g[0].length)) {
        return false;
    }

    // Check orientation (x, y)
    boolean canPlaceXY = true;
    if (r + x <= g.length && c + y <= g[0].length) {
        for (int i = r; i < r + x; i++) {
            for (int j = c; j < c + y; j++) {
                if (g[i][j]) {
                    canPlaceXY = false;
                    break;
                }
            }
            if (!canPlaceXY) break;
        }
        if (canPlaceXY) {
            for (int i = r; i < r + x; i++) {
                for (int j = c; j < c + y; j++) {
                    g[i][j] = true;
                }
            }
            return true;
        }
    }

    // Check orientation (y, x)
    boolean canPlaceYX = true;
    if (r + y <= g.length && c + x <= g[0].length) {
        for (int i = r; i < r + y; i++) {
            for (int j = c; j < c + x; j++) {
                if (g[i][j]) {
                    canPlaceYX = false;
                    break;
                }
            }
            if (!canPlaceYX) break;
        }
        if (canPlaceYX) {
            for (int i = r; i < r + y; i++) {
                for (int j = c; j < c + x; j++) {
                    g[i][j] = true;
                }
            }
            return true;
        }
    }

    return false;
}
